const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});
let counter = 0;
let S, T;

rl.on('line', (d) => {
  if (counter === 0) {
    S = d;
  }
  else {
    T = d;

    let ans = 'YES';
    let j = 0;
    for (let i = T.length - 1; i >=0; i--) {
      if (T[i] !== S[j]) {
        ans = 'NO';
        break;
      }
      j++;
    }

    console.log(ans);
  }

  counter++;
});
